<script setup lang="ts">import{confirmState,resolveConfirmation,toastState}from'@/shared/uiFeedback';</script>
<template><div v-if="confirmState.open" class="modal-bg confirm-layer" @click.self="resolveConfirmation(false)"><div class="modal confirm-modal" role="dialog" aria-modal="true"><h3>{{confirmState.title}}</h3><p>{{confirmState.message}}</p><div class="actions"><button class="btn secondary" @click="resolveConfirmation(false)">Cancelar</button><button class="btn" :class="{'danger-btn':confirmState.danger}" @click="resolveConfirmation(true)">{{confirmState.confirmText||'Confirmar'}}</button></div></div></div><Transition name="toast"><div v-if="toastState.visible" class="app-toast" :class="toastState.type" role="status">{{toastState.message}}</div></Transition></template>
